  await modal.getByLabel('Descripci\u00f3n *').fill('Test income'); await modal.getByLabel('Monto *', { exact: true }).fill('100'); await modal.getByLabel('Cuenta origen *').selectOption(personal.data.cuentas[0].ID); await modal.getByLabel('Categor\u00eda *', { exact: true }).selectOption(personal.data.categorias[0].ID);
