test('filtered XLSX CSV PDF and authenticated backup create actual downloads', async ({ page, personal }) => {
  personal.data.cuentas = fundedAccounts(); personal.data.movimientos = [{ ID: 'test-income', UPDATED_AT: 'v', OP_ID: 'test-op', FECHA: '2026-10-12', TIPO: 'Ingreso', CUENTA: 'test-bank', MONTO: 10, DESCRIPCION: '=TEST-FORMULA', ESTADO: 'Activo', ASIENTOS: '[{"CUENTA":"test-bank","CENTAVOS":1000}]' }]; await page.goto('/'); await navigatePersonal(page, 'Reportes');
  for (const kind of ['XLSX', 'CSV', 'PDF']) { const downloading = page.waitForEvent('download'); await page.getByRole('button', { name: `Descargar ${kind}`, exact: true }).click(); const download = await downloading; expect(download.suggestedFilename()).toBe(`personal-reporte.${kind.toLowerCase()}`); const stream = await download.createReadStream(); const chunks: Buffer[] = []; for await (const chunk of stream!) chunks.push(Buffer.from(chunk)); const bytes = Buffer.concat(chunks); expect(bytes.length).toBeGreaterThan(100); if (kind === 'CSV') expect(bytes.toString('utf8')).toContain("'=TEST-FORMULA"); if (kind === 'PDF') expect(bytes.subarray(0, 5).toString()).toBe('%PDF-'); if (kind === 'XLSX') { const XLSX = await import('xlsx'); const book = XLSX.read(bytes, { type: 'buffer' }); const cells = Object.values(book.Sheets.Personal); expect(cells.some((c: any) => c.v === '=TEST-FORMULA' && c.t === 's' && !c.f)).toBe(true); } }
  await navigatePersonal(page, 'Configuraci\u00f3n y respaldos'); const downloading = page.waitForEvent('download'); await page.getByRole('button', { name: 'Descargar respaldo JSON' }).click(); expect((await downloading).suggestedFilename()).toBe('personal-respaldo.json'); expect(personal.calls.some(c => c.action === 'personal-backup')).toBe(true);
});

