  personal.data.cuentas[2].PAGO_TOTAL_ESTADO = 100; await page.getByRole('button', { name: 'Actualizar datos personales' }).click(); await expect(statements).toContainText(`Saldo del estado: ${money(45)}`); expect(personal.data.cuentas[2].SALDO_ESTADO_PENDIENTE).toBe(personal.data.cuentas[2].DEUDA_ACTUAL);
